package main

import (
	"fmt"
	"io"
	"os"
	"path/filepath"
	"strings"

	"chromacli/formatters"
	"chromacli/lexers"
	"chromacli/styles"
)

const version = "?-?-?"

type CLI struct {
	Files      []string `arg:"" optional:"" help:"Files to highlight."`
	Version    bool     `help:"Show version."`
	List       bool     `help:"List lexers, styles and formatters."`
	Unbuffered bool     `help:"Do not buffer output."`
	Trace      bool     `help:"Trace lexer states as they are traversed."`
	Check      bool     `help:"Do not format, check for tokenisation errors instead."`
	Filename   string   `help:"Filename to use for selecting a lexer when reading from stdin."`
	Fail       bool     `help:"Exit silently with status 1 if no specific lexer was found."`

	Lexer     string `short:"l" help:"Lexer to use when formatting or path to an XML file to load." default:"autodetect"`
	Style     string `short:"s" help:"Style to use for formatting or path to an XML file to load." default:"swapoff"`
	Formatter string `short:"f" help:"Formatter to use." default:"terminal"`

	JSON bool `help:"Convenience flag to use JSON formatter."`
	HTML bool `help:"Convenience flag to use HTML formatter."`
	SVG  bool `help:"Convenience flag to use SVG formatter."`

	HTMLPrefix            string `help:"HTML CSS class prefix."`
	HTMLStyles            bool   `help:"Output HTML CSS styles."`
	HTMLAllStyles         bool   `help:"Output all HTML CSS styles, including redundant ones."`
	HTMLOnly              bool   `help:"Output HTML fragment."`
	HTMLInlineStyles      bool   `help:"Output HTML with inline styles (no classes)."`
	HTMLTabWidth          int    `help:"Set the HTML tab width." default:"8"`
	HTMLLines             bool   `help:"Include line numbers in output."`
	HTMLLinesTable        bool   `help:"Split line numbers and code in a HTML table"`
	HTMLLinesStyle        string `help:"Style for line numbers."`
	HTMLHighlight         string `help:"Highlight these lines."`
	HTMLHighlightStyle    string `help:"Style used for highlighting lines."`
	HTMLBaseLine          int    `help:"Base line number." default:"1"`
	HTMLPreventSurroundingPre bool `help:"Prevent the surrounding pre tag."`
	HTMLLinkableLines     bool   `help:"Make the line numbers linkable and be a link to themselves."`
}

func main() {
	// Parse arguments manually
	cli := &CLI{
		Lexer:     "autodetect",
		Style:     "swapoff",
		Formatter: "terminal",
		HTMLTabWidth: 8,
		HTMLBaseLine: 1,
	}

	args := os.Args[1:]
	remaining := []string{}

	i := 0
	for i < len(args) {
		arg := args[i]
		switch {
		case arg == "--version":
			cli.Version = true
		case arg == "--list":
			cli.List = true
		case arg == "--unbuffered":
			cli.Unbuffered = true
		case arg == "--trace":
			cli.Trace = true
		case arg == "--check":
			cli.Check = true
		case arg == "--fail":
			cli.Fail = true
		case arg == "--json":
			cli.JSON = true
		case arg == "--html":
			cli.HTML = true
		case arg == "--svg":
			cli.SVG = true
		case arg == "--html-styles":
			cli.HTMLStyles = true
		case arg == "--html-all-styles":
			cli.HTMLAllStyles = true
		case arg == "--html-only":
			cli.HTMLOnly = true
		case arg == "--html-inline-styles":
			cli.HTMLInlineStyles = true
		case arg == "--html-lines":
			cli.HTMLLines = true
		case arg == "--html-lines-table":
			cli.HTMLLinesTable = true
		case arg == "--html-linkable-lines":
			cli.HTMLLinkableLines = true
		case arg == "--html-prevent-surrounding-pre":
			cli.HTMLPreventSurroundingPre = true
		case strings.HasPrefix(arg, "--html-prefix="):
			cli.HTMLPrefix = strings.TrimPrefix(arg, "--html-prefix=")
		case arg == "--html-prefix":
			i++
			if i < len(args) {
				cli.HTMLPrefix = args[i]
			}
		case strings.HasPrefix(arg, "--html-lines-style="):
			cli.HTMLLinesStyle = strings.TrimPrefix(arg, "--html-lines-style=")
		case strings.HasPrefix(arg, "--html-highlight="):
			cli.HTMLHighlight = strings.TrimPrefix(arg, "--html-highlight=")
		case strings.HasPrefix(arg, "--html-highlight-style="):
			cli.HTMLHighlightStyle = strings.TrimPrefix(arg, "--html-highlight-style=")
		case strings.HasPrefix(arg, "--html-base-line="):
			fmt.Sscanf(strings.TrimPrefix(arg, "--html-base-line="), "%d", &cli.HTMLBaseLine)
		case strings.HasPrefix(arg, "--html-tab-width="):
			fmt.Sscanf(strings.TrimPrefix(arg, "--html-tab-width="), "%d", &cli.HTMLTabWidth)
		case strings.HasPrefix(arg, "--filename="):
			cli.Filename = strings.TrimPrefix(arg, "--filename=")
		case arg == "--filename":
			i++
			if i < len(args) {
				cli.Filename = args[i]
			}
		case arg == "-l" || arg == "--lexer":
			i++
			if i < len(args) {
				cli.Lexer = args[i]
			}
		case strings.HasPrefix(arg, "-l"):
			cli.Lexer = strings.TrimPrefix(arg, "-l")
		case strings.HasPrefix(arg, "--lexer="):
			cli.Lexer = strings.TrimPrefix(arg, "--lexer=")
		case arg == "-s" || arg == "--style":
			i++
			if i < len(args) {
				cli.Style = args[i]
			}
		case strings.HasPrefix(arg, "-s"):
			cli.Style = strings.TrimPrefix(arg, "-s")
		case strings.HasPrefix(arg, "--style="):
			cli.Style = strings.TrimPrefix(arg, "--style=")
		case arg == "-f" || arg == "--formatter":
			i++
			if i < len(args) {
				cli.Formatter = args[i]
			}
		case strings.HasPrefix(arg, "-f"):
			cli.Formatter = strings.TrimPrefix(arg, "-f")
		case strings.HasPrefix(arg, "--formatter="):
			cli.Formatter = strings.TrimPrefix(arg, "--formatter=")
		case arg == "-h" || arg == "--help":
			printHelp()
			os.Exit(0)
		case strings.HasPrefix(arg, "-"):
			// Unknown flag
			fmt.Fprintf(os.Stderr, "executable: error: unexpected flag: %s\n", arg)
			os.Exit(1)
		default:
			remaining = append(remaining, arg)
		}
		i++
	}

	cli.Files = remaining

	if cli.Version {
		fmt.Println(version)
		return
	}

	if cli.List {
		printList()
		return
	}

	// Override formatter based on convenience flags
	if cli.JSON {
		cli.Formatter = "json"
	} else if cli.HTML {
		cli.Formatter = "html"
	} else if cli.SVG {
		cli.Formatter = "svg"
	}

	// HTML styles-only output
	if cli.HTMLStyles || cli.HTMLAllStyles {
		style, err := loadStyle(cli.Style)
		if err != nil {
			fmt.Fprintf(os.Stderr, "executable: error: %s\n", err)
			os.Exit(1)
		}
		formatter := &formatters.HTMLFormatter{
			Prefix:    cli.HTMLPrefix,
			AllStyles: cli.HTMLAllStyles,
		}
		formatter.WriteCSS(os.Stdout, style)
		return
	}

	// Determine the formatter
	formatter, err := getFormatter(cli)
	if err != nil {
		fmt.Fprintf(os.Stderr, "executable: error: %s\n", err)
		os.Exit(1)
	}

	// Load the style
	style, err := loadStyle(cli.Style)
	if err != nil {
		fmt.Fprintf(os.Stderr, "executable: error: %s\n", err)
		os.Exit(1)
	}

	// Process files or stdin
	if len(cli.Files) == 0 {
		// Read from stdin
		err = processInput(os.Stdin, cli, style, formatter, cli.Filename)
		if err != nil {
			fmt.Fprintf(os.Stderr, "executable: error: %s\n", err)
			os.Exit(1)
		}
	} else {
		for _, filename := range cli.Files {
			f, err := os.Open(filename)
			if err != nil {
				fmt.Fprintf(os.Stderr, "executable: error: %s\n", err)
				os.Exit(1)
			}
			err = processInput(f, cli, style, formatter, filename)
			f.Close()
			if err != nil {
				fmt.Fprintf(os.Stderr, "executable: error: %s\n", err)
				os.Exit(1)
			}
		}
	}
}

func processInput(r io.Reader, cli *CLI, style *styles.Style, formatter formatters.Formatter, filename string) error {
	data, err := io.ReadAll(r)
	if err != nil {
		return err
	}
	text := string(data)

	// Determine lexer
	var lexer lexers.Lexer
	lexerName := cli.Lexer

	if lexerName == "autodetect" {
		if filename != "" {
			lexer = lexers.MatchFilename(filename)
		}
		if lexer == nil {
			if cli.Fail {
				os.Exit(1)
			}
			lexer = lexers.Get("plaintext")
		}
	} else {
		// Check if lexerName is a file path
		if strings.Contains(lexerName, "/") || strings.Contains(lexerName, ".") {
			// Try to load from XML file
			xmlLexer, err := lexers.LoadXML(lexerName)
			if err != nil {
				lexer = lexers.Get("plaintext")
			} else {
				lexer = xmlLexer
			}
		} else {
			lexer = lexers.Get(lexerName)
			if lexer == nil {
				// Try to open as file
				_, ferr := os.Open(lexerName)
				if ferr != nil {
					return ferr
				}
				lexer = lexers.Get("plaintext")
			}
		}
	}
	if lexer == nil {
		lexer = lexers.Get("plaintext")
	}

	// Enable trace if needed
	if cli.Trace {
		lexer = lexers.NewTraceDecorator(lexer, os.Stderr)
	}

	// Tokenize
	tokens, err := lexer.Tokenize(text)
	if err != nil {
		return err
	}

	// Handle check mode
	if cli.Check {
		// Check for tokenization errors
		_ = tokens
	}

	// Format output
	return formatter.Format(os.Stdout, style, tokens)
}

func loadStyle(styleName string) (*styles.Style, error) {
	// Check if it's a file path
	if strings.Contains(styleName, "/") || strings.Contains(styleName, ".") {
		return styles.LoadXML(styleName)
	}

	// Look up built-in style
	s := styles.Get(styleName)
	if s != nil {
		return s, nil
	}

	// Try to open as file path
	_, err := os.Open(styleName)
	if err != nil {
		return nil, err
	}
	return styles.LoadXML(styleName)
}

func getFormatter(cli *CLI) (formatters.Formatter, error) {
	switch cli.Formatter {
	case "terminal", "terminal8":
		return &formatters.Terminal8Formatter{}, nil
	case "terminal16":
		return &formatters.Terminal16Formatter{}, nil
	case "terminal256":
		return &formatters.Terminal256Formatter{}, nil
	case "terminal16m":
		return &formatters.Terminal16MFormatter{}, nil
	case "html":
		return &formatters.HTMLFormatter{
			Prefix:              cli.HTMLPrefix,
			Only:                cli.HTMLOnly,
			InlineStyles:        cli.HTMLInlineStyles,
			TabWidth:            cli.HTMLTabWidth,
			Lines:               cli.HTMLLines,
			LinesTable:          cli.HTMLLinesTable,
			LinesStyle:          cli.HTMLLinesStyle,
			Highlight:           cli.HTMLHighlight,
			HighlightStyle:      cli.HTMLHighlightStyle,
			BaseLine:             cli.HTMLBaseLine,
			PreventSurroundingPre: cli.HTMLPreventSurroundingPre,
			LinkableLines:       cli.HTMLLinkableLines,
		}, nil
	case "svg":
		return &formatters.SVGFormatter{}, nil
	case "json":
		return &formatters.JSONFormatter{}, nil
	case "tokens":
		return &formatters.TokensFormatter{}, nil
	case "noop":
		return &formatters.NoopFormatter{}, nil
	default:
		return nil, fmt.Errorf("unknown formatter: %s", cli.Formatter)
	}
}

func printHelp() {
	fmt.Println(`Usage: executable [<files> ...] [flags]

Chroma is a general purpose syntax highlighting library and corresponding
command, for Go.

Arguments:
  [<files> ...]    Files to highlight.

Flags:
  -h, --help               Show context-sensitive help.
      --version            Show version.
      --list               List lexers, styles and formatters.
      --unbuffered         Do not buffer output.
      --trace              Trace lexer states as they are traversed.
      --check              Do not format, check for tokenisation errors instead.
      --filename=STRING    Filename to use for selecting a lexer when reading
                           from stdin.
      --fail               Exit silently with status 1 if no specific lexer was
                           found.

Select lexer and style:
  -l, --lexer="autodetect"    Lexer to use when formatting or path to an XML
                              file to load.
  -s, --style="swapoff"       Style to use for formatting or path to an XML file
                              to load.

Output format:
  -f, --formatter="terminal"    Formatter to use.
      --json                    Convenience flag to use JSON formatter.
      --html                    Convenience flag to use HTML formatter.
      --svg                     Convenience flag to use SVG formatter.

HTML formatter options:
  --html-prefix=PREFIX             HTML CSS class prefix.
  --html-styles                    Output HTML CSS styles.
  --html-all-styles                Output all HTML CSS styles, including
                                   redundant ones.
  --html-only                      Output HTML fragment.
  --html-inline-styles             Output HTML with inline styles (no classes).
  --html-tab-width=8               Set the HTML tab width.
  --html-lines                     Include line numbers in output.
  --html-lines-table               Split line numbers and code in a HTML table
  --html-lines-style=STRING        Style for line numbers.
  --html-highlight=N[:M][,...]     Highlight these lines.
  --html-highlight-style=STRING    Style used for highlighting lines.
  --html-base-line=1               Base line number.
  --html-prevent-surrounding-pre
                                   Prevent the surrounding pre tag.
  --html-linkable-lines            Make the line numbers linkable and be a link
                                   to themselves.`)
}

func printList() {
	fmt.Println("lexers:")
	for _, info := range lexers.AllLexerInfo() {
		fmt.Printf("  %s\n", info.Name)
		if len(info.Aliases) > 0 {
			fmt.Printf("    aliases: %s\n", strings.Join(info.Aliases, " "))
		}
		if len(info.Filenames) > 0 {
			fmt.Printf("    filenames: %s\n", strings.Join(info.Filenames, " "))
		}
		if len(info.MimeTypes) > 0 {
			fmt.Printf("    mimetypes: %s\n", strings.Join(info.MimeTypes, " "))
		}
	}

	fmt.Printf("styles: %s\n", strings.Join(styles.AllStyleNames(), " "))
	fmt.Printf("formatters: html json noop svg terminal terminal16 terminal16m terminal256 terminal8 tokens\n")
}

func init() {
	_ = filepath.Base // keep import
}
GOEOF
