package lexers

import (
	"chromacli/token"
	"encoding/json"
	"fmt"
	"io"
	"os"
	"regexp"
	"strings"
	"time"
	"unicode/utf8"
)

// Lexer interface
type Lexer interface {
	Name() string
	Tokenize(text string) ([]token.Token, error)
}

// LexerInfo contains metadata about a lexer
type LexerInfo struct {
	Name      string
	Aliases   []string
	Filenames []string
	MimeTypes []string
}

// Rule represents a single lexer rule
type Rule struct {
	Pattern  *regexp.Regexp
	PatternStr string
	Type     token.TokenType
	// State transitions
	PushState string
	PopState  bool
	// Action: can emit multiple tokens from groups
	Groups   []token.TokenType
}

// State represents a lexer state with its rules
type State struct {
	Name  string
	Rules []*Rule
}

// RegexLexer is a regex-based state machine lexer
type RegexLexer struct {
	info   LexerInfo
	states map[string]*State
}

func (l *RegexLexer) Name() string {
	return l.info.Name
}

// tokenizeState processes the text in the given state, appending tokens
func (l *RegexLexer) tokenize(text string, stateStack []string, trace io.Writer) ([]token.Token, error) {
	var tokens []token.Token
	pos := 0

	for pos <= len(text) {
		if pos == len(text) {
			break
		}

		currentStateName := stateStack[len(stateStack)-1]
		state, ok := l.states[currentStateName]
		if !ok {
			// Unknown state, emit as error and advance
			_, size := utf8.DecodeRuneInString(text[pos:])
			tokens = append(tokens, token.Token{Type: token.Error, Value: text[pos : pos+size]})
			pos += size
			continue
		}

		matched := false
		for ruleIdx, rule := range state.Rules {
			loc := rule.Pattern.FindStringIndex(text[pos:])
			if loc == nil || loc[0] != 0 {
				continue
			}

			matchStr := text[pos : pos+loc[1]]

			if trace != nil {
				start := time.Now()
				elapsed := float64(time.Since(start).Microseconds()) / 1000.0
				traceEntry := map[string]interface{}{
					"lexer":     l.info.Name,
					"state":     currentStateName,
					"rule":      ruleIdx,
					"pattern":   rule.PatternStr,
					"pos":       pos,
					"length":    loc[1],
					"elapsedMs": elapsed,
				}
				data, _ := json.Marshal(traceEntry)
				fmt.Fprintf(trace, "%s\n", data)
			}

			if len(rule.Groups) > 0 {
				// Emit multiple tokens based on groups
				submatches := rule.Pattern.FindStringSubmatch(text[pos:])
				if len(submatches) > 1 {
					for i, groupType := range rule.Groups {
						if i+1 < len(submatches) && submatches[i+1] != "" {
							tokens = appendToken(tokens, token.Token{Type: groupType, Value: submatches[i+1]})
						}
					}
				}
			} else {
				// Emit a single token
				tokens = appendToken(tokens, token.Token{Type: rule.Type, Value: matchStr})
			}

			pos += loc[1]

			// Handle state transitions
			if rule.PopState {
				if len(stateStack) > 1 {
					stateStack = stateStack[:len(stateStack)-1]
				}
			} else if rule.PushState != "" {
				stateStack = append(stateStack, rule.PushState)
			}

			matched = true
			break
		}

		if !matched {
			// No rule matched, emit error token and advance one rune
			_, size := utf8.DecodeRuneInString(text[pos:])
			if size == 0 {
				break
			}
			tokens = appendToken(tokens, token.Token{Type: token.Error, Value: text[pos : pos+size]})
			pos += size
		}
	}

	return tokens, nil
}

