package lexers

import (
	"path/filepath"
	"sort"
	"strings"
)

var registry []*LexerEntry

type LexerEntry struct {
	info  LexerInfo
	lexer Lexer
}

// register adds a lexer to the registry
func register(l Lexer, info LexerInfo) {
	registry = append(registry, &LexerEntry{info: info, lexer: l})
}

// Get finds a lexer by name or alias
func Get(name string) Lexer {
	nameLower := strings.ToLower(name)
	for _, entry := range registry {
		if strings.ToLower(entry.info.Name) == nameLower {
			return entry.lexer
		}
		for _, alias := range entry.info.Aliases {
			if strings.ToLower(alias) == nameLower {
				return entry.lexer
			}
		}
	}
	return nil
}

// MatchFilename finds a lexer by filename
func MatchFilename(filename string) Lexer {
	base := filepath.Base(filename)
	for _, entry := range registry {
		for _, pattern := range entry.info.Filenames {
			if matched, _ := filepath.Match(pattern, base); matched {
				return entry.lexer
			}
		}
	}
	return nil
}

// MatchMimeType finds a lexer by MIME type
func MatchMimeType(mimeType string) Lexer {
	for _, entry := range registry {
		for _, mt := range entry.info.MimeTypes {
			if mt == mimeType {
				return entry.lexer
			}
		}
	}
	return nil
}

// AllLexerInfo returns info for all registered lexers, sorted by name
func AllLexerInfo() []LexerInfo {
	var infos []LexerInfo
	for _, entry := range registry {
		infos = append(infos, entry.info)
	}
	sort.Slice(infos, func(i, j int) bool {
		return infos[i].Name < infos[j].Name
	})
	return infos
}
