package lexers

import (
	"chromacli/token"
	"fmt"
	"regexp"
	"strings"
)

// LexerBuilder helps build RegexLexers
type LexerBuilder struct {
	info   LexerInfo
	states map[string][]*Rule
}

func NewBuilder(name string, aliases []string, filenames []string, mimetypes []string) *LexerBuilder {
	return &LexerBuilder{
		info: LexerInfo{
			Name:      name,
			Aliases:   aliases,
			Filenames: filenames,
			MimeTypes: mimetypes,
		},
		states: make(map[string][]*Rule),
	}
}

// R adds a rule to the named state
func (b *LexerBuilder) R(state string, rules ...*Rule) *LexerBuilder {
	b.states[state] = append(b.states[state], rules...)
	return b
}

// Rule creates a simple token rule
func R(pattern string, typ token.TokenType, pushState ...string) *Rule {
	re, err := compileRegex(pattern)
	if err != nil {
		panic(fmt.Sprintf("invalid pattern %q: %v", pattern, err))
	}
	r := &Rule{
		Pattern:    re,
		PatternStr: pattern,
		Type:       typ,
	}
	if len(pushState) > 0 {
		if pushState[0] == "#pop" {
			r.PopState = true
		} else {
			r.PushState = pushState[0]
		}
	}
	return r
}

// Rg creates a rule that emits multiple tokens based on capture groups
func Rg(pattern string, types ...token.TokenType) *Rule {
	re, err := compileRegex(pattern)
	if err != nil {
		panic(fmt.Sprintf("invalid pattern %q: %v", pattern, err))
	}
	return &Rule{
		Pattern:    re,
		PatternStr: pattern,
		Groups:     types,
	}
}

// Include adds all rules from another state
func (b *LexerBuilder) Include(targetState, sourceState string) *LexerBuilder {
	// Mark for inclusion - we'll resolve later
	b.states[targetState] = append(b.states[targetState], &Rule{
		Pattern:    nil,
		PatternStr: "#include:" + sourceState,
	})
	return b
}

// Build creates the RegexLexer
func (b *LexerBuilder) Build() *RegexLexer {
	// Resolve includes
	resolved := make(map[string][]*Rule)
	for stateName, rules := range b.states {
		resolved[stateName] = b.resolveRules(rules, b.states, 0)
	}

	states := make(map[string]*State)
	for name, rules := range resolved {
		states[name] = &State{Name: name, Rules: rules}
	}

	return &RegexLexer{
		info:   b.info,
		states: states,
	}
}

func (b *LexerBuilder) resolveRules(rules []*Rule, allStates map[string][]*Rule, depth int) []*Rule {
	if depth > 10 {
		return rules
	}
	var result []*Rule
	for _, r := range rules {
		if r.Pattern == nil && strings.HasPrefix(r.PatternStr, "#include:") {
			sourceName := strings.TrimPrefix(r.PatternStr, "#include:")
			if sourceRules, ok := allStates[sourceName]; ok {
				resolved := b.resolveRules(sourceRules, allStates, depth+1)
				result = append(result, resolved...)
			}
		} else {
			result = append(result, r)
		}
	}
	return result
}

// compileRegex compiles a Go regex from a chroma pattern
func compileRegex(pattern string) (*regexp.Regexp, error) {
	// Process pattern escapes
	p := pattern

	// \A in chroma means start of string/line - in Go we handle by matching at position 0
	// Convert \A to ^ with specific handling

	return regexp.Compile(`(?s)` + p)
}

// compileAnchoredRegex creates a pattern that only matches at position 0
// by always using FindStringIndex and checking loc[0] == 0
func init() {
	_ = regexp.MustCompile  // keep import
}
GOEOF
