import json
import re

with open('/tmp/all_styles.json') as f:
    all_styles = json.load(f)

# Parse all styles to get their CSS token entries
css_pattern = re.compile(r'/\* ([\w\s]+?) \*/ (?:\.bg|\.chroma(?:\s+\.[\w]+)?)\s*\{([^}]+)\}')

def parse_style_entry(css_value):
    """Parse a CSS value string into a StyleEntry struct"""
    entry = {}
    # Remove trailing semicolons and split by ;
    parts = re.split(r';', css_value)
    for part in parts:
        part = part.strip()
        if not part:
            continue
        if ':' not in part:
            continue
        prop, _, val = part.partition(':')
        prop = prop.strip()
        val = val.strip()
        if prop == 'color' and val != 'inherit':
            entry['color'] = val
        elif prop == 'background-color':
            entry['background'] = val
        elif prop == 'font-weight' and val == 'bold':
            entry['bold'] = True
        elif prop == 'font-style' and val == 'italic':
            entry['italic'] = True
        elif prop == 'text-decoration' and 'underline' in val:
            entry['underline'] = True
    return entry

def format_go_entry(name, entry):
    """Format a style entry as Go code"""
    parts = []
    if 'color' in entry:
        c = entry['color'].lstrip('#')
        r, g, b = int(c[0:2], 16), int(c[2:4], 16), int(c[4:6], 16)
        parts.append(f'Color: Color({r},{g},{b})')
    if 'background' in entry:
        c = entry['background'].lstrip('#')
        r, g, b = int(c[0:2], 16), int(c[2:4], 16), int(c[4:6], 16)
        parts.append(f'Background: Color({r},{g},{b})')
    if entry.get('bold'):
        parts.append('Bold: true')
    if entry.get('italic'):
        parts.append('Italic: true')
    if entry.get('underline'):
        parts.append('Underline: true')
    if not parts:
        return None
    return f'token.{name}: {{' + ', '.join(parts) + '}'

all_parsed = {}
for style_name, css in all_styles.items():
    entries = {}
    for m in css_pattern.finditer(css):
        token_name = m.group(1).strip()
        css_value = m.group(2).strip()
        parsed = parse_style_entry(css_value)
        if parsed:
            entries[token_name] = parsed
    all_parsed[style_name] = entries

with open('/tmp/parsed_styles2.json', 'w') as f:
    json.dump(all_parsed, f, indent=2)

print(f"Parsed {len(all_parsed)} styles")
print("\nSample (monokai Background):", all_parsed['monokai'].get('Background'))
