# Now let me write all the Go code.
# I'll start with a comprehensive implementation.

# First, let me understand the exact regex library to use.
# Chroma uses Go's regexp package which is RE2.
# The patterns use \p{L}, \p{N} which Go's regexp supports.
# They also use (?i) for case-insensitive, (?s) for dot-all, etc.

# Let me test if Go's regexp can handle the Python patterns:
cat > /tmp/test_regex.go << 'EOF'
package main

import (
    "fmt"
    "regexp"
)

func main() {
    patterns := []string{
        `[_\p{L}][_\p{L}\p{N}]*`,
        `\d(?:_?\d)*`,
        `[^\S\n]+`,
        `(?i)(rb|br|r)(")`,
        `(?<!\.)(\w+)`,
    }

    tests := []string{
        "hello", "1234", "   ", "rb\"", ".foo",
    }

    for _, p := range patterns {
        re, err := regexp.Compile(`(?s)` + p)
        if err != nil {
            fmt.Printf("FAIL: %q: %v\n", p, err)
            continue
        }
        for _, t := range tests {
            m := re.FindString(t)
            if m != "" {
                fmt.Printf("  %q matches %q -> %q\n", p[:20], t, m)
            }
        }
    }
}
EOF
cd /tmp && go run test_regex.go 2>&1

