cat > /home/agent/workspace/lexers.go << 'GOEOF'
package main

import (
	"encoding/json"
	"fmt"
	"os"
	"path/filepath"
	"regexp"
	"strings"
	"time"
	"unicode/utf8"
)

// RegexLexer implements a regex-based state machine lexer
type RegexLexer struct {
	info   LexerInfo
	states map[string][]LexerRule
}

// LexerInfo contains metadata about a lexer
type LexerInfo struct {
	Name      string
	Aliases   []string
	Filenames []string
	MimeTypes []string
}

// LexerRule represents a single lexer rule
type LexerRule struct {
	Pattern    *regexp.Regexp
	PatternStr string
	// Token type(s) to emit
	// If Groups is empty, emit single token of Type
	// If Groups is non-empty, emit one token per capture group
	Type       TokenType
	Groups     []TokenType
	// State transitions
	Push       string // push this state
	Pop        bool   // pop the current state
}

// TraceEntry contains trace data for a single rule match
type TraceEntry struct {
	Lexer     string  `json:"lexer"`
	State     string  `json:"state"`
	Rule      int     `json:"rule"`
	Pattern   string  `json:"pattern"`
	Pos       int     `json:"pos"`
	Length    int     `json:"length"`
	ElapsedMs float64 `json:"elapsedMs"`
}

// tokenize tokenizes the input text using the lexer
func tokenize(lexer *RegexLexer, text string, trace bool) ([]Token, []string) {
	if len(text) > 0 && text[len(text)-1] != '\n' {
		text = text + "\n"
	}

	var tokens []Token
	var traceEntries []string
	stateStack := []string{"root"}
	pos := 0

	for pos < len(text) {
		stateName := stateStack[len(stateStack)-1]
		rules, ok := lexer.states[stateName]
		if !ok {
			// Unknown state - emit error and advance
			_, size := utf8.DecodeRuneInString(text[pos:])
			if size == 0 {
				break
			}
			tokens = appendToken(tokens, Token{Type: Error, Value: text[pos : pos+size]})
			pos += size
			continue
		}

		matched := false
		for ruleIdx, rule := range rules {
			if rule.Pattern == nil {
				// Empty pattern - pop state
				if rule.Pop && len(stateStack) > 1 {
					stateStack = stateStack[:len(stateStack)-1]
				}
				matched = true
				break
			}

			loc := rule.Pattern.FindStringIndex(text[pos:])
			if loc == nil || loc[0] != 0 {
				continue
			}

			matchStr := text[pos : pos+loc[1]]
			startTime := time.Now()

			if trace {
				elapsed := float64(time.Since(startTime).Microseconds()) / 1000.0
				te := TraceEntry{
					Lexer:     lexer.info.Name,
					State:     stateName,
					Rule:      ruleIdx,
					Pattern:   rule.PatternStr,
					Pos:       pos,
					Length:    loc[1],
					ElapsedMs: elapsed,
				}
				data, _ := json.Marshal(te)
				traceEntries = append(traceEntries, string(data))
			}

			if len(rule.Groups) > 0 {
				// Group rule: emit one token per capture group
				submatches := rule.Pattern.FindStringSubmatch(text[pos:])
				if len(submatches) > 1 {
					for i, groupType := range rule.Groups {
						if i+1 < len(submatches) && len(submatches[i+1]) > 0 {
							tokens = appendToken(tokens, Token{Type: groupType, Value: submatches[i+1]})
						}
					}
				}
			} else {
				// Single token
				tokens = appendToken(tokens, Token{Type: rule.Type, Value: matchStr})
			}

			pos += loc[1]

			// Handle state transitions
			if rule.Pop {
				if len(stateStack) > 1 {
					stateStack = stateStack[:len(stateStack)-1]
				}
			} else if rule.Push != "" {
				stateStack = append(stateStack, rule.Push)
			}

			matched = true
			break
		}

		if !matched {
			// No rule matched - emit error and advance one rune
			_, size := utf8.DecodeRuneInString(text[pos:])
			if size == 0 {
				break
			}
			tokens = appendToken(tokens, Token{Type: Error, Value: text[pos : pos+size]})
			pos += size
		}
	}

	return tokens, traceEntries
}

// appendToken adds a token to the list, merging with the last if same type
func appendToken(tokens []Token, t Token) []Token {
	if len(tokens) > 0 && tokens[len(tokens)-1].Type == t.Type {
		tokens[len(tokens)-1].Value += t.Value
		return tokens
	}
	return append(tokens, t)
}

// Lexer registry
var lexerRegistry []*RegexLexer
var lexerMetaRegistry []LexerInfo

func registerMeta(info LexerInfo) {
	lexerMetaRegistry = append(lexerMetaRegistry, info)
}

func register(lexer *RegexLexer) {
	lexerRegistry = append(lexerRegistry, lexer)
	// Also register metadata if not already present
	found := false
	for _, m := range lexerMetaRegistry {
		if m.Name == lexer.info.Name {
			found = true
			break
		}
	}
	if !found {
		lexerMetaRegistry = append(lexerMetaRegistry, lexer.info)
	}
}

func getLexer(name string) *RegexLexer {
	nameLower := strings.ToLower(name)
	for _, lex := range lexerRegistry {
		if strings.ToLower(lex.info.Name) == nameLower {
			return lex
		}
		for _, alias := range lex.info.Aliases {
			if strings.ToLower(alias) == nameLower {
				return lex
