	found := false
	for _, m := range lexerMetaRegistry {
		if m.Name == lexer.info.Name {
			found = true
			break
		}
	}
	if !found {
		lexerMetaRegistry = append(lexerMetaRegistry, lexer.info)
	}
}

func getLexer(name string) *RegexLexer {
	nameLower := strings.ToLower(name)
	for _, lex := range lexerRegistry {
		if strings.ToLower(lex.info.Name) == nameLower {
			return lex
		}
		for _, alias := range lex.info.Aliases {
			if strings.ToLower(alias) == nameLower {
				return lex
			}
		}
	}
	return nil
}

func matchFilename(filename string) *RegexLexer {
	base := filepath.Base(filename)
	for _, lex := range lexerRegistry {
		for _, pattern := range lex.info.Filenames {
			if matched, _ := filepath.Match(pattern, base); matched {
				return lex
			}
		}
	}
	return nil
}

func getAllLexerInfo() []LexerInfo {
	return lexerMetaRegistry
}

// compilePattern compiles a regex pattern with (?s) flag
func compilePattern(pattern string) *regexp.Regexp {
	// Convert \A to ^ for start of string matching
	p := strings.ReplaceAll(pattern, `\A`, `^`)

	re, err := regexp.Compile(`(?s)` + p)
	if err != nil {
		// Try without (?s) for some patterns
		re2, err2 := regexp.Compile(p)
		if err2 != nil {
			fmt.Fprintf(os.Stderr, "Pattern compile error %q: %v\n", pattern, err)
			return regexp.MustCompile(`^$`) // never matches
		}
		return re2
	}
	return re
}

// mustCompile panics on error
func mustCompile(pattern string) *regexp.Regexp {
	p := strings.ReplaceAll(pattern, `\A`, `^`)
	re, err := regexp.Compile(`(?s)` + p)
	if err != nil {
		panic(fmt.Sprintf("pattern %q: %v", pattern, err))
	}
	return re
}

// buildRule creates a simple rule
func buildRule(pattern string, typ TokenType, push ...string) LexerRule {
	r := LexerRule{
		Pattern:    compilePattern(pattern),
		PatternStr: pattern,
		Type:       typ,
	}
	if len(push) > 0 {
		if push[0] == "#pop" {
			r.Pop = true
		} else {
			r.Push = push[0]
		}
	}
	return r
}

// buildGroupRule creates a rule that emits multiple tokens
func buildGroupRule(pattern string, push string, types ...TokenType) LexerRule {
	r := LexerRule{
		Pattern:    compilePattern(pattern),
		PatternStr: pattern,
		Groups:     types,
	}
	if push == "#pop" {
		r.Pop = true
	} else if push != "" {
		r.Push = push
	}
	return r
}

// buildPopRule creates an empty rule that pops state
func buildPopRule() LexerRule {
	return LexerRule{Pop: true}
}

// Lookbehind wrapper: only matches if preceded by the given characters
type lookbehindRule struct {
	LexerRule
	notPrecededBy string // don't match if preceded by this char
}

// For patterns with lookbehind, we'll handle them specially
// by checking the character at pos-1 in the tokenize loop

// Note: Go's regexp doesn't support lookbehind, so we handle these specially
// The patterns like (?<!\.) are converted to a check after matching

func init() {
	_ = fmt.Sprintf
}
