package main

import (
	"encoding/json"
	"fmt"
	"os"
	"path/filepath"
	"regexp"
	"strings"
	"time"
	"unicode/utf8"
)

// LexerInfo contains metadata about a lexer
type LexerInfo struct {
	Name      string
	Aliases   []string
	Filenames []string
	MimeTypes []string
}

// LexerRule represents one rule in a lexer state
type LexerRule struct {
	Pattern    *regexp.Regexp
	PatternStr string
	Type       TokenType   // for single-token rules
	Groups     []TokenType // for group rules
	Push       string      // push this state
	Pop        bool        // pop current state
	// For lookbehind simulation
	NotPrecededByDot bool // simulate (?<!\.)
}

// RegexLexer is a regex-based state machine lexer
type RegexLexer struct {
	info   LexerInfo
	states map[string][]LexerRule
}

// traceEntry is used for --trace output
type traceEntry struct {
	Lexer     string  `json:"lexer"`
	State     string  `json:"state"`
	Rule      int     `json:"rule"`
	Pattern   string  `json:"pattern"`
	Pos       int     `json:"pos"`
	Length    int     `json:"length"`
	ElapsedMs float64 `json:"elapsedMs"`
}

// tokenize tokenizes the text and optionally produces trace output
func tokenize(lexer *RegexLexer, text string, trace bool) ([]Token, []string) {
	if len(text) > 0 && text[len(text)-1] != '\n' {
		text += "\n"
	}

	var tokens []Token
	var traceLines []string
	stack := []string{"root"}
	pos := 0

	for pos < len(text) {
		stateName := stack[len(stack)-1]
		rules, ok := lexer.states[stateName]
		if !ok {
			// Unknown state - advance one char as error
			_, sz := utf8.DecodeRuneInString(text[pos:])
			if sz == 0 {
				break
			}
			tokens = appendTok(tokens, Token{Type: Error, Value: text[pos : pos+sz]})
			pos += sz
			continue
		}

		matched := false
		for ri, rule := range rules {
			// Empty pattern = pop rule
			if rule.Pattern == nil {
				if rule.Pop && len(stack) > 1 {
					stack = stack[:len(stack)-1]
				}
				matched = true
				break
			}

			loc := rule.Pattern.FindStringIndex(text[pos:])
			if loc == nil || loc[0] != 0 {
				continue
			}

			// Check lookbehind-not-dot
			if rule.NotPrecededByDot && pos > 0 && text[pos-1] == '.' {
				continue
			}

			matchStr := text[pos : pos+loc[1]]

			if trace {
				start := time.Now()
				_ = start
				te := traceEntry{
					Lexer:     lexer.info.Name,
					State:     stateName,
					Rule:      ri,
					Pattern:   rule.PatternStr,
					Pos:       pos,
					Length:    loc[1],
					ElapsedMs: float64(time.Since(start).Microseconds()) / 1000.0,
				}
				data, _ := json.Marshal(te)
				traceLines = append(traceLines, string(data))
			}

			if len(rule.Groups) > 0 {
				// Emit one token per capture group
				subs := rule.Pattern.FindStringSubmatch(text[pos:])
				for i, gtype := range rule.Groups {
					if i+1 < len(subs) && subs[i+1] != "" {
						tokens = appendTok(tokens, Token{Type: gtype, Value: subs[i+1]})
					}
				}
			} else {
				tokens = appendTok(tokens, Token{Type: rule.Type, Value: matchStr})
			}

			pos += loc[1]

			if rule.Pop {
				if len(stack) > 1 {
					stack = stack[:len(stack)-1]
				}
			} else if rule.Push != "" {
				stack = append(stack, rule.Push)
			}

			matched = true
			break
		}

		if !matched {
			_, sz := utf8.DecodeRuneInString(text[pos:])
			if sz == 0 {
				break
			}
			tokens = appendTok(tokens, Token{Type: Error, Value: text[pos : pos+sz]})
			pos += sz
		}
	}

	return tokens, traceLines
}

// appendTok adds a token, merging with last if same type
func appendTok(tokens []Token, t Token) []Token {
	if len(tokens) > 0 && tokens[len(tokens)-1].Type == t.Type {
		tokens[len(tokens)-1].Value += t.Value
		return tokens
	}
	return append(tokens, t)
}

// Registry
var lexerRegistry []*RegexLexer
var lexerMeta []LexerInfo

func registerMeta(info LexerInfo) {
	lexerMeta = append(lexerMeta, info)
}

func register(lex *RegexLexer) {
	lexerRegistry = append(lexerRegistry, lex)
}

func getLexer(name string) *RegexLexer {
	nl := strings.ToLower(name)
	for _, lex := range lexerRegistry {
		if strings.ToLower(lex.info.Name) == nl {
			return lex
		}
		for _, a := range lex.info.Aliases {
			if strings.ToLower(a) == nl {
				return lex
			}
		}
	}
	return nil
}

func matchFilename(fn string) *RegexLexer {
	base := filepath.Base(fn)
	for _, lex := range lexerRegistry {
		for _, p := range lex.info.Filenames {
			if m, _ := filepath.Match(p, base); m {
				return lex
			}
		}
	}
	return nil
}

func getAllLexerInfo() []LexerInfo {
	return lexerMeta
}

// Helper functions for building lexers

func pat(p string) *regexp.Regexp {
	// Handle \A anchor
	p2 := strings.ReplaceAll(p, `\A`, `^`)
	re, err := regexp.Compile(`(?s)` + p2)
	if err != nil {
		fmt.Fprintf(os.Stderr, "Bad pattern %q: %v\n", p, err)
		return regexp.MustCompile(`(?s)a^`) // never matches
	}
	return re
}

func R(p string, t TokenType, push ...string) LexerRule {
	r := LexerRule{Pattern: pat(p), PatternStr: p, Type: t}
	if len(push) > 0 {
		if push[0] == "#pop" {
			r.Pop = true
		} else {
			r.Push = push[0]
		}
	}
	return r
}

func Rnb(p string, t TokenType) LexerRule {
	// Rule with not-preceded-by-dot check (simulates (?<!\.))
	r := LexerRule{Pattern: pat(p), PatternStr: p, Type: t, NotPrecededByDot: true}
	return r
}

func Rg(p string, push string, types ...TokenType) LexerRule {
	r := LexerRule{Pattern: pat(p), PatternStr: p, Groups: types}
	if push == "#pop" {
		r.Pop = true
	} else if push != "" {
		r.Push = push
	}
	return r
}

func Pop() LexerRule {
	return LexerRule{Pop: true}
}
