// parseHighlight parses highlight ranges like "1,3:5,7"
func parseHighlight(s string) map[int]bool {
	result := make(map[int]bool)
	if s == "" {
		return result
	}
	for _, part := range strings.Split(s, ",") {
		part = strings.TrimSpace(part)
		if strings.Contains(part, ":") {
			rangeParts := strings.SplitN(part, ":", 2)
			start, err1 := strconv.Atoi(strings.TrimSpace(rangeParts[0]))
			end, err2 := strconv.Atoi(strings.TrimSpace(rangeParts[1]))
			if err1 == nil && err2 == nil {
				for i := start; i <= end; i++ {
					result[i] = true
				}
			}
		} else {
			n, err := strconv.Atoi(part)
			if err == nil {
				result[n] = true
			}
		}
	}
	return result
}

func formatHTML(w io.Writer, style *Style, tokens []Token, opts HTMLFormatterOptions) error {
	pfx := opts.Prefix
	if opts.TabWidth <= 0 {
		opts.TabWidth = 8
	}
	if opts.BaseLine <= 0 {
		opts.BaseLine = 1
	}

	highlighted := parseHighlight(opts.Highlight)

	// Build HTML content
	var buf strings.Builder

	// Split tokens into lines for line numbering
	type lineToken struct {
		tokens []Token
	}

	var lines [][]Token
	var currentLine []Token

	for _, tok := range tokens {
		parts := strings.SplitAfter(tok.Value, "\n")
		for i, part := range parts {
			if part == "" {
				continue
			}
			currentLine = append(currentLine, Token{Type: tok.Type, Value: part})
			if strings.HasSuffix(part, "\n") {
				lines = append(lines, currentLine)
				currentLine = nil
			}
		}
	}
	if len(currentLine) > 0 {
		lines = append(lines, currentLine)
	}

	renderToken := func(tok Token) string {
		if tok.Type == Text || tok.Type == TextWhitespace {
			return html.EscapeString(tok.Value)
		}
		e := style.GetEntry(tok.Type)
		cls := tokenTypeToCSSClass[tok.Type]

		if opts.InlineStyles {
			if !colorSet(e.Color) && !colorSet(e.Background) && !e.Bold && !e.Italic && !e.Underline {
				return html.EscapeString(tok.Value)
			}
			var styleParts []string
			if colorSet(e.Color) {
				styleParts = append(styleParts, fmt.Sprintf("color:#%02x%02x%02x", e.Color.R, e.Color.G, e.Color.B))
			}
			if colorSet(e.Background) {
				styleParts = append(styleParts, fmt.Sprintf("background-color:#%02x%02x%02x", e.Background.R, e.Background.G, e.Background.B))
			}
			if e.Bold {
				styleParts = append(styleParts, "font-weight:bold")
			}
			if e.Italic {
				styleParts = append(styleParts, "font-style:italic")
			}
			if e.Underline {
				styleParts = append(styleParts, "text-decoration:underline")
			}
			if len(styleParts) == 0 {
				return html.EscapeString(tok.Value)
			}
			return fmt.Sprintf("<span style=\"%s\">%s</span>",
				strings.Join(styleParts, ";"), html.EscapeString(tok.Value))
		}

		if cls == "" {
			return html.EscapeString(tok.Value)
		}
		return fmt.Sprintf("<span class=\"%s%s\">%s</span>", pfx, cls, html.EscapeString(tok.Value))
	}

	if opts.PreventSurroundingPre {
		// No pre wrapper - just render tokens inline
		for _, tok := range tokens {
			buf.WriteString(renderToken(tok))
		}
		fmt.Fprint(w, buf.String())
		return nil
	}

	if opts.LinesTable {
		// Table format with separate line numbers
		lineNums := &strings.Builder{}
		codeLines := &strings.Builder{}

		for lineIdx, line := range lines {
			lineNum := lineIdx + opts.BaseLine
			fmt.Fprintf(lineNums, "<span class=\"%slnt\">%d\n</span>", pfx, lineNum)

			codeLines.WriteString(fmt.Sprintf("<span class=\"%sline", pfx))
			if highlighted[lineNum] {
				codeLines.WriteString(" " + pfx + "hl")
			}
			codeLines.WriteString(fmt.Sprintf("\"><span class=\"%scl\">", pfx))
			for _, tok := range line {
				codeLines.WriteString(renderToken(tok))
			}
			codeLines.WriteString("</span></span>")
		}

		var preStyle string
		if opts.InlineStyles {
			bg := style.Entries["Background"]
			preStyle = fmt.Sprintf(" style=\"color:#%02x%02x%02x;background-color:#%02x%02x%02x;-webkit-text-size-adjust:none;\"",
				bg.Color.R, bg.Color.G, bg.Color.B, bg.Background.R, bg.Background.G, bg.Background.B)
		}

		fmt.Fprintf(&buf, "<div class=\"%schroma\">\n", pfx)
		fmt.Fprintf(&buf, "<table class=\"%slntable\"><tr><td class=\"%slntd\">\n", pfx, pfx)
		fmt.Fprintf(&buf, "<pre class=\"%schroma\"%s>%s</pre></td>\n", pfx, preStyle, lineNums.String())
		fmt.Fprintf(&buf, "<td class=\"%slntd\">\n", pfx)
		fmt.Fprintf(&buf, "<pre class=\"%schroma\"%s><code>%s</code></pre></td></tr></table>\n", pfx, preStyle, codeLines.String())
		fmt.Fprintf(&buf, "</div>\n")

	} else if opts.Lines || !opts.InlineStyles {
		// Standard pre format
		var preClass string
		var preStyle string

		if opts.InlineStyles {
			bg := style.Entries["Background"]
			preStyle = fmt.Sprintf(" style=\"color:#%02x%02x%02x;background-color:#%02x%02x%02x;-webkit-text-size-adjust:none;\"",
				bg.Color.R, bg.Color.G, bg.Color.B, bg.Background.R, bg.Background.G, bg.Background.B)
		} else {
			preClass = fmt.Sprintf(" class=\"%schroma\"", pfx)
		}

		fmt.Fprintf(&buf, "<pre%s%s><code>", preClass, preStyle)

		for lineIdx, line := range lines {
			lineNum := lineIdx + opts.BaseLine

			lineClass := fmt.Sprintf("%sline", pfx)
			if highlighted[lineNum] {
				lineClass += " " + pfx + "hl"
			}
			fmt.Fprintf(&buf, "<span class=\"%s\">", lineClass)

			if opts.Lines {
				if opts.LinkableLines {
					fmt.Fprintf(&buf, "<span class=\"%sln\" id=\"L%d\"><a class=\"%slnlinks\" href=\"#L%d\">%d</a></span>",
						pfx, lineNum, pfx, lineNum, lineNum)
				} else {
					fmt.Fprintf(&buf, "<span class=\"%sln\">%d</span>", pfx, lineNum)
				}
			}

			fmt.Fprintf(&buf, "<span class=\"%scl\">", pfx)
			for _, tok := range line {
				buf.WriteString(renderToken(tok))
			}
			buf.WriteString("</span></span>")
		}

		buf.WriteString("</code></pre>")
	} else {
		// Simple pre format (inline styles)
		bg := style.Entries["Background"]
		preStyle := fmt.Sprintf(" style=\"color:#%02x%02x%02x;background-color:#%02x%02x%02x;-webkit-text-size-adjust:none;\"",
			bg.Color.R, bg.Color.G, bg.Color.B, bg.Background.R, bg.Background.G, bg.Background.B)

		fmt.Fprintf(&buf, "<pre%s><code>", preStyle)
		for lineIdx, line := range lines {
			lineNum := lineIdx + opts.BaseLine
			if highlighted[lineNum] {
				fmt.Fprintf(&buf, "<span style=\"background-color:#e5e5e5\">")
			}
			fmt.Fprintf(&buf, "<span style=\"display:flex;\"><span>")
			for _, tok := range line {
				buf.WriteString(renderToken(tok))
			}
			buf.WriteString("</span></span>")
			if highlighted[lineNum] {
				buf.WriteString("</span>")
			}
		}
		buf.WriteString("</code></pre>")
	}

	if !opts.Only {
		// Full HTML page
		bg := style.Entries["Background"]
		var bgCSS strings.Builder

		fmt.Fprintf(w, "<html>\n<style type=\"text/css\">\n")
		writeCSS(w, style, &HTMLFormatterOptions{Prefix: pfx})

		bgCSS.WriteString(fmt.Sprintf("body { "))
		if colorSet(bg.Color) {
			bgCSS.WriteString(fmt.Sprintf("color:#%02x%02x%02x;", bg.Color.R, bg.Color.G, bg.Color.B))
		}
		if colorSet(bg.Background) {
			bgCSS.WriteString(fmt.Sprintf("background-color:#%02x%02x%02x;", bg.Background.R, bg.Background.G, bg.Background.B))
		}
		bgCSS.WriteString("; }\n")

		fmt.Fprint(w, bgCSS.String())
		fmt.Fprintf(w, "</style><body class=\"%sbg\">\n", pfx)
		fmt.Fprint(w, buf.String())
		fmt.Fprintf(w, "\n</body>\n</html>\n")
	} else {
		fmt.Fprint(w, buf.String())
	}

	return nil
}

// ============== SVG Formatter ==============

func formatSVG(w io.Writer, style *Style, tokens []Token) error {
	// Collect all text to determine size
	var lines []string
	var currentLine strings.Builder

	for _, tok := range tokens {
		for _, r := range tok.Value {
			if r == '\n' {
				lines = append(lines, currentLine.String())
				currentLine.Reset()
			} else {
				currentLine.WriteRune(r)
			}
		}
	}
	if currentLine.Len() > 0 {
		lines = append(lines, currentLine.String())
	}

	// Calculate dimensions
	maxWidth := 0
	for _, l := range lines {
		if len(l) > maxWidth {
			maxWidth = len(l)
		}
	}

	charWidth := 8.0   // approx char width in pixels at 14px
	lineHeight := 18.0 // approx line height
	fontSize := 14.0
	paddingLeft := 0.0
	paddingTop := lineHeight

	width := paddingLeft + float64(maxWidth)*charWidth
	height := paddingTop + float64(len(lines))*lineHeight

	bg := style.Entries["Background"]

	fmt.Fprintf(w, "<?xml version=\"1.0\" encoding=\"UTF-8\"?>\n")
	fmt.Fprintf(w, "<!DOCTYPE svg PUBLIC \"-//W3C//DTD SVG 1.0//EN\" \"http://www.w3.org/TR/2001/REC-SVG-20010904/DTD/svg10.dtd\">\n")
	fmt.Fprintf(w, "<svg width=\"%.0fpx\" height=\"%.0fpx\" xmlns=\"http://www.w3.org/2000/svg\">\n", width, height)

	// Write embedded font (simplified - just reference the font)
	fmt.Fprintf(w, "<style>\n@font-face {\n\tfont-family: 'Liberation Mono';\n")
	// TODO: embed actual font data
	fmt.Fprintf(w, "\tfont-weight: normal;\n\tfont-style: normal;\n}\n</style>")

	// Background
	bgColor := "#ffffff"
	fgColor := "#000000"
	if colorSet(bg.Background) {
		bgColor = fmt.Sprintf("#%02x%02x%02x", bg.Background.R, bg.Background.G, bg.Background.B)
	}
	if colorSet(bg.Color) {
		fgColor = fmt.Sprintf("#%02x%02x%02x", bg.Color.R, bg.Color.G, bg.Color.B)
	}

	fmt.Fprintf(w, "<rect width=\"100%%\" height=\"100%%\" fill=\"%s\"/>\n", bgColor)
	fmt.Fprintf(w, "<g font-family=\"Liberation Mono\" font-size=\"%.0fpx\" fill=\"%s\">\n", fontSize, fgColor)

	// Render each line
	for lineIdx, line := range lines {
		y := (float64(lineIdx)+1) * lineHeight / fontSize
		fmt.Fprintf(w, "<text x=\"%.0f\" y=\"%.6fem\" xml:space=\"preserve\">", paddingLeft, y)

		// Find tokens for this line
		// (simplified: just render the text)
		fmt.Fprintf(w, "%s", svgEscape(line))
		fmt.Fprintf(w, "\n</text>\n")
	}

	fmt.Fprintf(w, "</g>\n</svg>\n\n")
	return nil
}

func svgEscape(s string) string {
	var b strings.Builder
	for _, r := range s {
		switch r {
		case '&':
			b.WriteString("&amp;")
		case '<':
			b.WriteString("&lt;")
		case '>':
			b.WriteString("&gt;")
		case '"':
			b.WriteString("&quot;")
		case ' ':
			b.WriteString("&#160;")
		default:
			b.WriteRune(r)
		}
	}
	return b.String()
}

