func formatJSON(w io.Writer, tokens []Token) error {
	fmt.Fprintf(w, "[\n")
	for i, tok := range tokens {
		comma := ","
		if i == len(tokens)-1 {
			comma = ""
		}
		val := jsonEscape(tok.Value)
		fmt.Fprintf(w, "  {\"type\":%q,\"value\":\"%s\"}%s\n", tok.Type, val, comma)
	}
	fmt.Fprintf(w, "]\n")
	return nil
}

func jsonEscape(s string) string {
	var b strings.Builder
	for _, r := range s {
		switch r {
		case '"':
			b.WriteString(`\"`)
		case '\\':
			b.WriteString(`\\`)
		case '\n':
			b.WriteString(`\n`)
		case '\r':
			b.WriteString(`\r`)
		case '\t':
			b.WriteString(`\t`)
		case '<':
			b.WriteString(`\u003c`)
		case '>':
			b.WriteString(`\u003e`)
		case '&':
			b.WriteString(`\u0026`)
		default:
			if r < 0x20 {
				fmt.Fprintf(&b, `\u%04x`, r)
			} else {
				b.WriteRune(r)
			}
		}
	}
	return b.String()
}

