		{LiteralStringOther, "LiteralStringOther", "sx"},
		{LiteralStringRegex, "LiteralStringRegex", "sr"},
		{LiteralStringSingle, "LiteralStringSingle", "s1"},
		{LiteralStringSymbol, "LiteralStringSymbol", "ss"},
		{LiteralNumber, "LiteralNumber", "m"},
		{LiteralNumberBin, "LiteralNumberBin", "mb"},
		{LiteralNumberFloat, "LiteralNumberFloat", "mf"},
		{LiteralNumberHex, "LiteralNumberHex", "mh"},
		{LiteralNumberInteger, "LiteralNumberInteger", "mi"},
		{LiteralNumberIntegerLong, "LiteralNumberIntegerLong", "il"},
		{LiteralNumberOct, "LiteralNumberOct", "mo"},
