func nearestCubeLevel(x uint8) int {
	levels := [6]int{0, 95, 135, 175, 215, 255}
	bestIdx := 0
	bestDist := abs(int(x) - levels[0])
	for i, l := range levels {
		d := abs(int(x) - l)
		if d < bestDist {
			bestDist = d
			bestIdx = i
		}
	}
	return bestIdx
