// ============== Token Formatter ==============

func formatTokens(w io.Writer, tokens []Token) error {
	for _, tok := range tokens {
		val := strings.ReplaceAll(tok.Value, `\`, `\\`)
		val = strings.ReplaceAll(val, `"`, `\"`)
		val = strings.ReplaceAll(val, "\n", `\n`)
		val = strings.ReplaceAll(val, "\t", `\t`)
		fmt.Fprintf(w, "&Token{%s, %q}\n", tok.Type, tok.Value)
	}
	return nil
}

// ============== Noop Formatter ==============

func formatNoop(w io.Writer, tokens []Token) error {
	for _, tok := range tokens {
		fmt.Fprint(w, tok.Value)
	}
	return nil
}

// ============== JSON Formatter ==============

func formatJSON(w io.Writer, tokens []Token) error {
	fmt.Fprintf(w, "[\n")
	for i, tok := range tokens {
		comma := ","
		if i == len(tokens)-1 {
			comma = ""
		}
		val := jsonEscape(tok.Value)
		fmt.Fprintf(w, "  {\"type\":%q,\"value\":\"%s\"}%s\n", tok.Type, val, comma)
	}
	fmt.Fprintf(w, "]\n")
	return nil
}

func jsonEscape(s string) string {
	var b strings.Builder
	for _, r := range s {
		switch r {
		case '"':
			b.WriteString(`\"`)
		case '\\':
			b.WriteString(`\\`)
		case '\n':
			b.WriteString(`\n`)
		case '\r':
			b.WriteString(`\r`)
		case '\t':
			b.WriteString(`\t`)
		case '<':
			b.WriteString(`\u003c`)
		case '>':
			b.WriteString(`\u003e`)
		case '&':
			b.WriteString(`\u0026`)
		default:
			if r < 0x20 {
				fmt.Fprintf(&b, `\u%04x`, r)
			} else {
				b.WriteRune(r)
			}
		}
	}
	return b.String()
}

// ============== Terminal Formatters ==============

// CSS class to ANSI code mapping for terminal8
var cssClassToANSI8 = map[string][2]int{} // token type -> {bold, color}

func colorToANSI8(c Color) (bold bool, ansi int) {
	if c.R == 0 && c.G == 0 && c.B == 0 {
		return false, 30 // black
	}

	// Convert to 256-color then to 8-color
	idx256 := colorTo256(c)
	return color256To8(idx256)
}

func colorToANSI16(c Color) int {
	// Find closest 16-color
	if c.R == 0 && c.G == 0 && c.B == 0 {
		return 30 // black
	}

	idx256 := colorTo256(c)
	bold, ansi8 := color256To8(idx256)

	if bold {
		return 90 + (ansi8 - 30) // bright colors (90-97)
	}
	return ansi8
}

func colorToANSI256(c Color) int {
	return colorTo256(c)
}

func nearestCubeLevel(x uint8) int {
	levels := [6]int{0, 95, 135, 175, 215, 255}
	bestIdx := 0
	bestDist := abs(int(x) - levels[0])
	for i, l := range levels {
		d := abs(int(x) - l)
		if d < bestDist {
			bestDist = d
			bestIdx = i
		}
	}
	return bestIdx
}

func abs(x int) int {
	if x < 0 {
		return -x
	}
	return x
}

func colorTo256(c Color) int {
	r, g, b := int(c.R), int(c.G), int(c.B)

	// Find nearest cube color
	cr := nearestCubeLevel(c.R)
	cg := nearestCubeLevel(c.G)
	cb := nearestCubeLevel(c.B)
	cubeIdx := 16 + 36*cr + 6*cg + cb

	cubeR, cubeG, cubeB := cube256ToRGB(cubeIdx)
	distCube := (r-cubeR)*(r-cubeR) + (g-cubeG)*(g-cubeG) + (b-cubeB)*(b-cubeB)

	// Find nearest grayscale
	grayAvg := (r + g + b) / 3
	grayIdxRaw := int(math.Round(float64(grayAvg-8)/10)) + 232

	if grayIdxRaw < 232 || grayIdxRaw > 255 {
		return cubeIdx
	}

	grayVal := 8 + (grayIdxRaw-232)*10
	distGray := (r-grayVal)*(r-grayVal) + (g-grayVal)*(g-grayVal) + (b-grayVal)*(b-grayVal)

	if distCube <= distGray {
		return cubeIdx
	}
	return grayIdxRaw
}

func cube256ToRGB(idx int) (int, int, int) {
	if idx < 232 {
		n := idx - 16
		b := n % 6
		g := (n / 6) % 6
		r := n / 36
		levels := [6]int{0, 95, 135, 175, 215, 255}
		return levels[r], levels[g], levels[b]
	}
	gray := 8 + (idx-232)*10
	return gray, gray, gray
}

// Lookup table for 256-color cube to 8-color conversion (indices 16-231)
// Values encode: bold*100 + ansi_code
var cube256To8Table = [216]int{
	30, 34, 34, 34, 134, 134, 32, 36, 36, 36, 36, 134, 32, 36, 36, 36, 36, 33,
	32, 36, 36, 36, 136, 136, 132, 132, 36, 136, 136, 136, 132, 132, 136, 136, 136, 136,
	31, 35, 35, 35, 35, 134, 130, 130, 130, 33, 33, 33, 32, 130, 130, 33, 33, 33,
	32, 36, 36, 33, 33, 33, 132, 132, 36, 33, 136, 136, 132, 132, 136, 136, 136, 136,
	31, 35, 35, 35, 35, 135, 130, 130, 130, 33, 33, 33, 130, 130, 33, 33, 33, 33,
	32, 130, 33, 33, 33, 33, 133, 37, 37, 37, 37, 37, 133, 133, 37, 37, 37, 37,
	31, 35, 35, 35, 135, 135, 130, 130, 130, 33, 33, 33, 130, 130, 33, 33, 33, 33,
	133, 130, 33, 33, 33, 33, 133, 133, 37, 37, 37, 37, 133, 133, 37, 37, 37, 37,
	131, 35, 35, 135, 135, 135, 131, 130, 33, 33, 33, 33, 133, 130, 33, 33, 33, 33,
	133, 133, 37, 37, 37, 37, 133, 133, 37, 37, 37, 37, 133, 133, 37, 37, 37, 137,
	131, 131, 135, 135, 135, 135, 131, 131, 135, 135, 135, 135, 133, 37, 37, 37, 37, 37,
	133, 133, 37, 37, 37, 37, 133, 133, 37, 37, 37, 37, 133, 133, 37, 37, 137, 137,
}

func color256To8(idx int) (bold bool, ansi int) {
	if idx < 16 {
		// Standard 16 colors
		if idx < 8 {
			return false, 30 + idx
		}
		return true, 30 + (idx - 8)
	}
	if idx < 232 {
		// 6x6x6 cube
		val := cube256To8Table[idx-16]
		if val >= 100 {
			return true, val - 100
		}
		return false, val
	}
	// Grayscale (232-255)
	grayIdx := idx - 232 // 0-23
	if grayIdx < 6 {
		return false, 30 // dark -> black
	} else if grayIdx < 12 {
		return true, 30 // bold black (dark gray)
	} else if grayIdx < 18 {
		return false, 37 // light gray
	}
	return true, 37 // bright white
}

func formatTerminal8(w io.Writer, style *Style, tokens []Token) error {
	for _, tok := range tokens {
		entry := style.GetEntry(tok.Type)
		if !colorSet(entry.Color) && !entry.Bold && !entry.Italic {
			fmt.Fprint(w, tok.Value)
			continue
		}

		bold, ansi := colorToANSI8(entry.Color)
		if entry.Bold {
			bold = true
		}

		if bold {
			fmt.Fprintf(w, "\x1b[1m\x1b[%dm%s\x1b[0m", ansi, tok.Value)
		} else {
			fmt.Fprintf(w, "\x1b[%dm%s\x1b[0m", ansi, tok.Value)
		}
	}
	return nil
}

func formatTerminal16(w io.Writer, style *Style, tokens []Token) error {
	for _, tok := range tokens {
		entry := style.GetEntry(tok.Type)
		if !colorSet(entry.Color) && !entry.Bold && !entry.Italic {
			fmt.Fprint(w, tok.Value)
			continue
		}

		ansi16 := colorToANSI16(entry.Color)
		fmt.Fprintf(w, "\x1b[%dm%s\x1b[0m", ansi16, tok.Value)
	}
	return nil
}

func formatTerminal256(w io.Writer, style *Style, tokens []Token) error {
	for _, tok := range tokens {
		entry := style.GetEntry(tok.Type)
		if !colorSet(entry.Color) && !entry.Bold && !entry.Italic {
			fmt.Fprint(w, tok.Value)
			continue
		}

		idx := colorToANSI256(entry.Color)
		fmt.Fprintf(w, "\x1b[38;5;%dm%s\x1b[0m", idx, tok.Value)
	}
	return nil
}

func formatTerminal16M(w io.Writer, style *Style, tokens []Token) error {
	for _, tok := range tokens {
		entry := style.GetEntry(tok.Type)
		if !colorSet(entry.Color) && !entry.Bold && !entry.Italic {
			fmt.Fprint(w, tok.Value)
			continue
		}

		c := entry.Color
		fmt.Fprintf(w, "\x1b[38;2;%d;%d;%dm%s\x1b[0m", c.R, c.G, c.B, tok.Value)
	}
	return nil
}

func colorSet(c Color) bool {
	return c.R != 0 || c.G != 0 || c.B != 0
}

