func styleToCSSProps(e StyleEntry) string {
	var parts []string
	if colorSet(e.Color) {
		parts = append(parts, fmt.Sprintf("color: #%02x%02x%02x", e.Color.R, e.Color.G, e.Color.B))
	}
	if colorSet(e.Background) {
		parts = append(parts, fmt.Sprintf("background-color: #%02x%02x%02x", e.Background.R, e.Background.G, e.Background.B))
	}
	if e.Bold {
		parts = append(parts, "font-weight: bold")
	}
	if e.Italic {
		parts = append(parts, "font-style: italic")
	}
	if e.Underline {
		parts = append(parts, "text-decoration: underline")
	}
	return strings.Join(parts, "; ")
}

func writeCSS(w io.Writer, style *Style, opts *HTMLFormatterOptions) {
	pfx := ""
	if opts != nil {
		pfx = opts.Prefix
	}

	// Background
	bg := style.Entries["Background"]
	var bgParts []string
	if colorSet(bg.Color) {
		bgParts = append(bgParts, fmt.Sprintf("color: #%02x%02x%02x", bg.Color.R, bg.Color.G, bg.Color.B))
	}
	if colorSet(bg.Background) {
		bgParts = append(bgParts, fmt.Sprintf("background-color: #%02x%02x%02x", bg.Background.R, bg.Background.G, bg.Background.B))
	}
	if len(bgParts) > 0 {
		fmt.Fprintf(w, "/* Background */ .%sbg { %s; }\n", pfx, strings.Join(bgParts, "; "))
	} else {
		fmt.Fprintf(w, "/* Background */ .%sbg { }\n", pfx)
	}

	// PreWrapper
	var preParts []string
	if colorSet(bg.Color) {
		preParts = append(preParts, fmt.Sprintf("color: #%02x%02x%02x", bg.Color.R, bg.Color.G, bg.Color.B))
	}
	if colorSet(bg.Background) {
		preParts = append(preParts, fmt.Sprintf("background-color: #%02x%02x%02x", bg.Background.R, bg.Background.G, bg.Background.B))
	}
	preParts = append(preParts, "-webkit-text-size-adjust: none")
	fmt.Fprintf(w, "/* PreWrapper */ .%schroma { %s; }\n", pfx, strings.Join(preParts, "; "))

	// Error
	if e := style.Entries[Error]; colorSet(e.Color) || colorSet(e.Background) {
		props := styleToCSSProps(e)
		fmt.Fprintf(w, "/* Error */ .%schroma .%serr { %s }\n", pfx, pfx, props)
	}

	// LineLink
	fmt.Fprintf(w, "/* LineLink */ .%schroma .%slnlinks { outline: none; text-decoration: none; color: inherit }\n", pfx, pfx)

	// LineTableTD
	fmt.Fprintf(w, "/* LineTableTD */ .%schroma .%slntd { vertical-align: top; padding: 0; margin: 0; border: 0; }\n", pfx, pfx)

	// LineTable
	fmt.Fprintf(w, "/* LineTable */ .%schroma .%slntable { border-spacing: 0; padding: 0; margin: 0; border: 0; }\n", pfx, pfx)

	// LineHighlight
	lhColor := style.LineHighlight
	if colorSet(lhColor) {
		fmt.Fprintf(w, "/* LineHighlight */ .%schroma .%shl { background-color: #%02x%02x%02x }\n", pfx, pfx, lhColor.R, lhColor.G, lhColor.B)
	} else {
		fmt.Fprintf(w, "/* LineHighlight */ .%schroma .%shl { background-color: #e5e5e5 }\n", pfx, pfx)
	}

	// LineNumbersTable
	lntColor := style.LineNumbersTable
	if !colorSet(lntColor) {
		lntColor = Color{R: 127, G: 127, B: 127}
	}
	fmt.Fprintf(w, "/* LineNumbersTable */ .%schroma .%slnt { white-space: pre; -webkit-user-select: none; user-select: none; margin-right: 0.4em; padding: 0 0.4em 0 0.4em;color: #%02x%02x%02x }\n",
		pfx, pfx, lntColor.R, lntColor.G, lntColor.B)

	// LineNumbers
	lnColor := style.LineNumbers
	if !colorSet(lnColor) {
		lnColor = Color{R: 127, G: 127, B: 127}
	}
	fmt.Fprintf(w, "/* LineNumbers */ .%schroma .%sln { white-space: pre; -webkit-user-select: none; user-select: none; margin-right: 0.4em; padding: 0 0.4em 0 0.4em;color: #%02x%02x%02x }\n",
		pfx, pfx, lnColor.R, lnColor.G, lnColor.B)

	// Line
	fmt.Fprintf(w, "/* Line */ .%schroma .%sline { display: flex; }\n", pfx, pfx)

	// Write other token types
	orderedTypes := []struct{ typ, comment, cls string }{
